entries[18500] = { ["name"] = "Flügelstoß", ["text"] = "Wirken in 0.5 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 5594 Schaden zu und stößt sie zurück. Dieser Effekt ignoriert Rüstung." }
