entries[18502] = { ["name"] = "Fluch von Hakkar", ["text"] = "200 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nEntzieht einem Feind alle 5 Sek. 5 Mana und überträgt sie 2 Min. lang auf den Zaubernden." }
entries[18503] = { ["name"] = "Verhexung", ["text"] = "20 Mana 20 Meter Reichweite\nSofort\nTransformiert einen Feind in ein Huhn, sodass er 5 Sek. lang nicht angreifen oder Zauber wirken kann." }
