entries[18543] = { ["name"] = "Flammenpeitsche", ["text"] = "30 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 15 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[18545] = { ["name"] = "Skorpidgift", ["text"] = "10 Mana 5 - 30 Meter Reichweite\nBenötigt Distanzwaffe\nSticht einen Feind und verringert 20 Sek. lang Stärke und Beweglichkeit des Ziels um 1." }
